import{_ as a,o as s,c as n,a2 as e}from"./chunks/framework.BZO4qERu.js";const g=JSON.parse('{"title":"角色状态","description":"","frontmatter":{},"headers":[],"relativePath":"guide/characters-states.md","filePath":"guide/characters-states.md","lastUpdated":1787389693000}'),r={name:"guide/characters-states.md"};function o(d,t,l,p,i,c){return s(),n("div",null,[...t[0]||(t[0]=[e(`<h1 id="角色状态" tabindex="-1">角色状态 <a class="header-anchor" href="#角色状态" aria-label="Permalink to &quot;角色状态&quot;">​</a></h1><p>角色状态是对于<strong>行动顺序表</strong>而言的行动状态，这与<strong>特效施加的状态</strong>要分开讨论。角色状态的优先级是最高的，它决定了角色是否可以行动。</p><blockquote><p>特效状态（增益/负面/常见特效状态）见 <a href="/guide/effects.html">特效概述</a>。</p></blockquote><h2 id="状态类型" tabindex="-1">状态类型 <a class="header-anchor" href="#状态类型" aria-label="Permalink to &quot;状态类型&quot;">​</a></h2><h3 id="控制态" tabindex="-1">控制态 <a class="header-anchor" href="#控制态" aria-label="Permalink to &quot;控制态&quot;">​</a></h3><p>控制态是能够影响角色行动和决策的状态，<strong>高级别控制态将覆盖低级别控制态，也将覆盖常态</strong>。例如：完全行动不能 覆盖 行动受限。</p><table tabindex="0"><thead><tr><th>状态</th><th>效果</th><th>允许操作</th></tr></thead><tbody><tr><td><strong>完全行动不能</strong></td><td>回合将被跳过</td><td>无</td></tr><tr><td><strong>行动受限</strong></td><td>决策受限</td><td>只能使用特殊物品</td></tr><tr><td><strong>战斗不能</strong></td><td>无法战斗</td><td>只能使用物品</td></tr><tr><td><strong>技能受限</strong></td><td>无法使用技能</td><td>可以普通攻击，可以使用物品</td></tr><tr><td><strong>攻击受限</strong></td><td>无法普通攻击</td><td>可以使用技能，可以使用物品</td></tr></tbody></table><blockquote><p><strong>特殊情况</strong>：当同时存在技能受限和攻击受限时，它们会因为&quot;只能使用物品&quot;的共同点而被<strong>战斗不能</strong>覆盖。</p></blockquote><h3 id="吟唱态" tabindex="-1">吟唱态 <a class="header-anchor" href="#吟唱态" aria-label="Permalink to &quot;吟唱态&quot;">​</a></h3><p>吟唱态是特殊的状态，它归<strong>行动顺序表</strong>管理：</p><table tabindex="0"><thead><tr><th>状态</th><th>说明</th></tr></thead><tbody><tr><td><strong>吟唱中</strong></td><td>角色正在吟唱魔法，此回合将在行动阶段结算吟唱的魔法效果，无法手动决策</td></tr><tr><td><strong>预释放爆发技</strong></td><td>角色已预释放爆发技，此回合将在行动阶段结算爆发技，需要选择爆发技的目标，无法取消爆发技和执行其他行动指令</td></tr></tbody></table><ul><li>当角色处于<strong>吟唱中</strong>状态，被施加控制态（<strong>攻击受限除外</strong>）时，控制态通常需要向行动顺序表发送信号，<strong>打断此角色的施法</strong>，以取消吟唱态</li><li><strong>预释放爆发技</strong>是所有状态中级别最高的，它<strong>无法被任何状态覆盖</strong>，直到角色完成爆发技的释放<strong>或者死亡</strong></li></ul><h3 id="常态" tabindex="-1">常态 <a class="header-anchor" href="#常态" aria-label="Permalink to &quot;常态&quot;">​</a></h3><p>此状态允许角色在行动阶段<strong>自主决策</strong>，是默认状态。</p><h2 id="状态覆盖优先级" tabindex="-1">状态覆盖优先级 <a class="header-anchor" href="#状态覆盖优先级" aria-label="Permalink to &quot;状态覆盖优先级&quot;">​</a></h2><p>由此可见，角色的状态具有以下覆盖优先级：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>预释放爆发技</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>完全行动不能</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>行动受限</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>战斗不能</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>[ 技能受限 → 吟唱中 ] / 攻击受限</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>常态</span></span></code></pre></div><blockquote><p>方括号表示技能受限优先于吟唱中（技能受限会打断吟唱），攻击受限与它们同级但不会打断吟唱。</p></blockquote>`,18)])])}const u=a(r,[["render",o]]);export{g as __pageData,u as default};
